import { OpsRestaurantSettingsClient } from '@/components/features/restaurant-settings/OpsRestaurantSettingsClient';

import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Google Business Profile · Nab a Table Ops',
  description: 'Connect a Google account and link the correct GBP location to this restaurant.',
};

export default function GoogleBusinessProfileSettingsPage() {
  return <OpsRestaurantSettingsClient view="google-business-profile" />;
}

'use client';

import dynamic from 'next/dynamic';
import { useEffect, type ReactNode } from 'react';

import { OpsEmptyState } from '@/components/features/ops-shell/patterns/OpsEmptyState';
import { Skeleton } from '@/components/ui/skeleton';
import { useOpsActiveMembership, useOpsSession } from '@/contexts/ops-session';

import type { RestaurantSettingsView } from './types';

const SettingsSectionSkeleton = ({ title }: { title: string }) => (
  <div className="rounded-lg border border-border/60 bg-muted/30 p-6" aria-busy="true" role="status">
    <p className="text-sm font-medium text-foreground">{title}</p>
    <div className="mt-3 space-y-3">
      <Skeleton className="h-4 w-40" />
      <Skeleton className="h-10 w-full" />
      <Skeleton className="h-10 w-3/4" />
    </div>
  </div>
);

const RestaurantProfileSection = dynamic(() => import('./RestaurantProfileSection').then((m) => m.RestaurantProfileSection), {
  loading: () => <SettingsSectionSkeleton title="Loading profile" />,
});

const GoogleBusinessProfileSection = dynamic(
  () =>
    import('./google-business-profile/GoogleBusinessProfileSection').then(
      (m) => m.GoogleBusinessProfileSection,
    ),
  {
    loading: () => <SettingsSectionSkeleton title="Loading Google Business Profile" />,
  },
);

const AvailabilityOccasionsCommandCenter = dynamic(
  () =>
    import('./AvailabilityOccasionsCommandCenter').then((m) => m.AvailabilityOccasionsCommandCenter),
  {
    loading: () => <SettingsSectionSkeleton title="Loading availability and occasions" />,
  },
);

const OpsTeamManagementClient = dynamic(() => import('../team').then((m) => m.OpsTeamManagementClient), {
  loading: () => <SettingsSectionSkeleton title="Loading team" />,
});

export type OpsRestaurantSettingsClientProps = {
  defaultRestaurantId?: string | null;
  view: RestaurantSettingsView;
};

export function OpsRestaurantSettingsClient({ defaultRestaurantId, view }: OpsRestaurantSettingsClientProps) {
  const { memberships, activeRestaurantId, setActiveRestaurantId } = useOpsSession();
  const activeMembership = useOpsActiveMembership();

  useEffect(() => {
    if (activeRestaurantId) {
      return;
    }
    if (defaultRestaurantId) {
      setActiveRestaurantId(defaultRestaurantId);
      return;
    }
    if (memberships[0]) {
      setActiveRestaurantId(memberships[0].restaurantId);
    }
  }, [activeRestaurantId, defaultRestaurantId, memberships, setActiveRestaurantId]);

  if (memberships.length === 0) {
    return (
      <section className="mx-auto flex min-h-[60vh] max-w-2xl items-center justify-center p-8">
        <OpsEmptyState
          title="No restaurant access"
          description="You need access to at least one restaurant to manage settings. Contact an owner or admin for access."
        />
      </section>
    );
  }

  const selectedMembership =
    activeMembership ??
    memberships.find((membership) => membership.restaurantId === activeRestaurantId) ??
    memberships[0] ??
    null;

  const selectedRestaurantId = selectedMembership?.restaurantId ?? null;

  const renderByView: Record<RestaurantSettingsView, (context: { restaurantId: string | null }) => ReactNode> = {
    profile: ({ restaurantId }) => <RestaurantProfileSection restaurantId={restaurantId} />,
    'google-business-profile': ({ restaurantId }) => (
      <GoogleBusinessProfileSection restaurantId={restaurantId} />
    ),
    availability: ({ restaurantId }) => <AvailabilityOccasionsCommandCenter restaurantId={restaurantId} />,
    team: () => <OpsTeamManagementClient />,
  };

  return <div className="space-y-6">{renderByView[view]({ restaurantId: selectedRestaurantId })}</div>;
}

'use client';

import { useSearchParams } from 'next/navigation';
import { useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import {
  useOpsCreateGoogleBusinessProfileDraft,
  useOpsDisconnectGoogleBusinessProfile,
  useOpsGoogleBusinessProfileConnection,
  useOpsLinkGoogleBusinessProfileLocation,
} from '@/hooks/ops/useOpsGoogleBusinessProfile';
import { useOpsOperatingHours } from '@/hooks/ops/useOpsOperatingHours';
import { useOpsRestaurantDetails } from '@/hooks/ops/useOpsRestaurantDetails';
import { useOpsServicePeriods } from '@/hooks/ops/useOpsServicePeriods';
import {
  OPS_RESTAURANTS_BASE,
  type GoogleBusinessProfileAvailableLocation,
} from '@/services/ops/restaurants';

import { AlignmentCard } from './components/AlignmentCard';
import { ConnectCard } from './components/ConnectCard';
import { LinkedSummaryCard } from './components/LinkedSummaryCard';
import { LocationPickerCard } from './components/LocationPickerCard';
import { PageHeader } from './components/PageHeader';
import { SnapshotCard } from './components/SnapshotCard';
import { WorkflowCard } from './components/WorkflowCard';
import { deriveProfileVerification } from './googleBusinessProfileVerification';
import { buildDriftReport } from './lib/drift';

type GoogleBusinessProfileSectionProps = {
  restaurantId: string | null;
};

function buildLocationValue(location: GoogleBusinessProfileAvailableLocation): string {
  return JSON.stringify({
    accountName: location.accountName,
    accountId: location.accountId,
    locationName: location.locationName,
    locationId: location.locationId,
  });
}

function LoadingSkeleton() {
  return (
    <div className="space-y-6">
      <div className="space-y-2">
        <Skeleton className="h-8 w-64" />
        <Skeleton className="h-4 w-48" />
      </div>
      <Skeleton className="h-56 w-full rounded-lg" />
    </div>
  );
}

export function GoogleBusinessProfileSection({ restaurantId }: GoogleBusinessProfileSectionProps) {
  const searchParams = useSearchParams();
  const connectionQuery = useOpsGoogleBusinessProfileConnection(restaurantId);
  const profileQuery = useOpsRestaurantDetails(restaurantId);
  const operatingHoursQuery = useOpsOperatingHours(restaurantId);
  const servicePeriodsQuery = useOpsServicePeriods(restaurantId);
  const linkMutation = useOpsLinkGoogleBusinessProfileLocation(restaurantId);
  const disconnectMutation = useOpsDisconnectGoogleBusinessProfile(restaurantId);
  const createDraftMutation = useOpsCreateGoogleBusinessProfileDraft(restaurantId);

  const [selectedLocationValue, setSelectedLocationValue] = useState('');
  const [wantsRelink, setWantsRelink] = useState(false);

  useEffect(() => {
    const gbpStatus = searchParams.get('gbp');
    const message = searchParams.get('message');
    if (!gbpStatus) return;

    if (gbpStatus === 'connected') {
      toast.success('Google Business Profile connected. Choose a location to finish linking.');
    } else if (gbpStatus === 'error') {
      toast.error(message ?? 'Google Business Profile connection failed.');
    }

    if (typeof window !== 'undefined') {
      const url = new URL(window.location.href);
      url.searchParams.delete('gbp');
      url.searchParams.delete('message');
      window.history.replaceState({}, '', url.toString());
    }
  }, [searchParams]);

  const data = connectionQuery.data;

  useEffect(() => {
    if (!data) return;

    if (data.externalLocationName && data.externalAccountName && !wantsRelink) {
      const linkedLocation = data.availableLocations.find(
        (location) =>
          location.locationName === data.externalLocationName &&
          location.accountName === data.externalAccountName,
      );
      if (linkedLocation) {
        setSelectedLocationValue(buildLocationValue(linkedLocation));
        return;
      }
    }

    if (!selectedLocationValue && data.availableLocations[0]) {
      setSelectedLocationValue(buildLocationValue(data.availableLocations[0]));
    }
  }, [data, selectedLocationValue, wantsRelink]);

  const selectedLocation = useMemo<GoogleBusinessProfileAvailableLocation | null>(() => {
    if (!data) return null;
    return (
      data.availableLocations.find(
        (location) => buildLocationValue(location) === selectedLocationValue,
      ) ?? null
    );
  }, [data, selectedLocationValue]);

  if (!restaurantId) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-sm text-muted-foreground">
          Select a restaurant using the sidebar switcher to manage its Google Business Profile
          connection.
        </CardContent>
      </Card>
    );
  }

  if (connectionQuery.isLoading && !data) {
    return <LoadingSkeleton />;
  }

  if (connectionQuery.error) {
    return (
      <Card>
        <CardContent className="py-6">
          <Alert variant="destructive">
            <AlertTitle>Unable to load Google Business Profile</AlertTitle>
            <AlertDescription className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <span>{connectionQuery.error.message}</span>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => void connectionQuery.refetch()}
              >
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        </CardContent>
      </Card>
    );
  }

  if (!data) {
    return null;
  }

  const connectHref = `${OPS_RESTAURANTS_BASE}/${restaurantId}/google-business-profile/connect`;
  const manageOnGoogleHref = data.externalPlaceId
    ? `https://www.google.com/maps/search/?api=1&query_place_id=${encodeURIComponent(data.externalPlaceId)}`
    : null;
  const hasLinkedLocation = Boolean(data.externalLocationId);
  const isLinked = data.status === 'linked' || data.status === 'sync_error';

  const showPicker =
    data.status === 'authorized' || data.status === 'reauth_required' || (isLinked && wantsRelink);

  const showConnect = !isLinked && !showPicker && data.status !== 'authorized';

  const handleLinkLocation = () => {
    if (!selectedLocation) {
      toast.error('Choose a location before linking.');
      return;
    }
    linkMutation.mutate(
      {
        accountName: selectedLocation.accountName,
        accountId: selectedLocation.accountId,
        locationName: selectedLocation.locationName,
        locationId: selectedLocation.locationId,
      },
      {
        onSuccess: () => {
          setWantsRelink(false);
          toast.success('Google Business Profile location linked.');
        },
        onError: (error) => toast.error(error.message),
      },
    );
  };

  const handleDisconnect = () => {
    disconnectMutation.mutate(undefined, {
      onSuccess: () => {
        setSelectedLocationValue('');
        setWantsRelink(false);
        toast.success('Google Business Profile disconnected.');
      },
      onError: (error) => toast.error(error.message),
    });
  };

  return (
    <div className="space-y-6">
      <PageHeader
        status={data.status}
        lastPullAt={data.lastPullAt}
        onRefresh={() => void connectionQuery.refetch()}
        isRefreshing={connectionQuery.isFetching}
        manageOnGoogleHref={manageOnGoogleHref}
        canDisconnect={data.status !== 'unlinked'}
        onDisconnect={handleDisconnect}
        isDisconnecting={disconnectMutation.isPending}
      />

      {showConnect ? (
        <ConnectCard
          connectHref={connectHref}
          isConfigured={data.isConfigured}
          isPendingAuth={data.status === 'pending_auth'}
          lastError={!isLinked ? data.lastError : null}
        />
      ) : null}

      {showPicker ? (
        <LocationPickerCard
          data={data}
          connectHref={connectHref}
          selectedLocation={selectedLocation}
          selectedLocationValue={selectedLocationValue}
          onSelectedLocationValueChange={setSelectedLocationValue}
          buildLocationValue={buildLocationValue}
          onLinkLocation={handleLinkLocation}
          isLinking={linkMutation.isPending}
          hasLinkedLocation={hasLinkedLocation}
        />
      ) : null}

      {isLinked ? (
        <>
          <LinkedSummaryCard
            data={data}
            manageOnGoogleHref={manageOnGoogleHref}
            onGenerateDraft={() =>
              createDraftMutation.mutate(undefined, {
                onSuccess: () => toast.success('GBP review draft generated.'),
                onError: (error) => toast.error(error.message),
              })
            }
            onChangeLocation={() => setWantsRelink(true)}
            isGeneratingDraft={createDraftMutation.isPending}
          />
          <WorkflowCard restaurantId={restaurantId} />

          <section
            aria-label="Secondary analysis"
            className="space-y-4 rounded-lg border border-dashed border-border bg-muted/20 p-4"
            data-testid="gbp-secondary-analysis"
          >
            <div className="space-y-1">
              <h2 className="text-sm font-semibold uppercase tracking-[0.18em] text-muted-foreground">
                Secondary analysis
              </h2>
              <p className="text-xs text-muted-foreground">
                Reference data and drift comparison. Use the Approval workflow above to make
                changes.
              </p>
            </div>
            <AlignmentCard
              report={buildDriftReport({
                profile: profileQuery.data,
                connection: data,
                verification: deriveProfileVerification({
                  profile: profileQuery.data,
                  connection: data,
                }),
              })}
              connection={data}
              operatingHours={operatingHoursQuery.data}
              servicePeriods={servicePeriodsQuery.data}
              isScheduleDataLoading={
                (operatingHoursQuery.isLoading && !operatingHoursQuery.data) ||
                (servicePeriodsQuery.isLoading && !servicePeriodsQuery.data)
              }
            />
            <SnapshotCard businessInfo={data.businessInfo} />
          </section>
        </>
      ) : null}
    </div>
  );
}

'use client';

import { ExternalLink, PencilLine, RefreshCcw } from 'lucide-react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { cn } from '@/lib/utils';

import { formatGbpDateTime } from '../lib/formatters';

import type { GoogleBusinessProfileConnection } from '@/services/ops/restaurants';

type LinkedSummaryCardProps = {
  data: GoogleBusinessProfileConnection;
  manageOnGoogleHref: string | null;
  onGenerateDraft: () => void;
  onChangeLocation: () => void;
  isGeneratingDraft: boolean;
};

function DetailRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="space-y-0.5">
      <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">{label}</p>
      <p className="text-sm text-foreground">{value}</p>
    </div>
  );
}

export function LinkedSummaryCard({
  data,
  manageOnGoogleHref,
  onGenerateDraft,
  onChangeLocation,
  isGeneratingDraft,
}: LinkedSummaryCardProps) {
  const hasSyncError = data.status === 'sync_error';
  const multipleLocations = data.availableLocations.length > 1;

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex flex-wrap items-center gap-2">
          {data.externalLocationTitle ?? 'Linked location'}
        </CardTitle>
        <CardDescription>
          {data.connectedGoogleEmail ? (
            <>
              Linked through{' '}
              <span className="font-medium text-foreground">{data.connectedGoogleEmail}</span>.
              Generate a review draft before publishing any Business Profile changes.
            </>
          ) : (
            'Nabatable keeps a cached snapshot of this Business Profile for verification.'
          )}
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-5">
        {hasSyncError && data.lastError ? (
          <Alert variant="destructive">
            <AlertTitle>Sync needs attention</AlertTitle>
            <AlertDescription>{data.lastError}</AlertDescription>
          </Alert>
        ) : null}

        <div className="grid gap-4 rounded-lg border bg-muted/40 p-4 sm:grid-cols-3">
          <DetailRow
            label="Location ID"
            value={data.externalLocationId ?? 'Unknown'}
          />
          <DetailRow
            label="Last fetched"
            value={formatGbpDateTime(data.lastPullAt) ?? 'Never'}
          />
          <DetailRow
            label="Last pushed"
            value={formatGbpDateTime(data.lastPushAt) ?? 'Never'}
          />
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <Button type="button" onClick={onGenerateDraft} disabled={isGeneratingDraft} size="lg">
            <RefreshCcw className={cn('mr-2 size-4', isGeneratingDraft && 'animate-spin')} />
            {isGeneratingDraft ? 'Generating...' : 'Generate review draft'}
          </Button>

          {manageOnGoogleHref ? (
            <Button type="button" variant="outline" asChild>
              <a href={manageOnGoogleHref} target="_blank" rel="noreferrer">
                <ExternalLink className="mr-2 size-4" />
                View on Google Maps
              </a>
            </Button>
          ) : null}

          {multipleLocations ? (
            <Button type="button" variant="ghost" onClick={onChangeLocation}>
              <PencilLine className="mr-2 size-4" />
              Change location
            </Button>
          ) : null}
        </div>
      </CardContent>
    </Card>
  );
}

'use client';

import {
  ArrowRightLeft,
  CheckCircle2,
  Circle,
  GitPullRequestArrow,
  Loader2,
  RefreshCw,
  Send,
} from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  useOpsCreateGoogleBusinessProfileDraft,
  useOpsGoogleBusinessProfileWorkflow,
  useOpsPreflightGoogleBusinessProfileDraftPublish,
  useOpsPublishGoogleBusinessProfileDraft,
  useOpsUpdateGoogleBusinessProfileDraft,
} from '@/hooks/ops/useOpsGoogleBusinessProfile';
import { cn } from '@/lib/utils';
import { deriveGoogleBusinessProfileWorkflowStage } from '@/services/ops/restaurants';

import { GoogleBusinessProfileSyncActionDialog } from '../GoogleBusinessProfileSyncActionDialog';
import { formatGbpDateTime } from '../lib/formatters';
import { DetailInspector } from './workflow/DetailInspector';
import { SectionInbox } from './workflow/SectionInbox';
import {
  buildDialogItems,
  buildSectionSummaries,
  formatAuditDirectionLabel,
  formatDraftStatusLabel,
  statusVariant,
} from './workflow/workflow-utils';

import type {
  GoogleBusinessProfileDraftPublishPreflight,
  GoogleBusinessProfileWorkflowStage,
} from '@/services/ops/restaurants';

type WorkflowCardProps = {
  restaurantId: string;
};

/* Re-export for external consumers */
export { humanFieldLabel } from './workflow/workflow-utils';

/* ── Stepper ─────────────────────────────────────── */

type StepDef = {
  key: GoogleBusinessProfileWorkflowStage | 'publish';
  label: string;
  completedAt: GoogleBusinessProfileWorkflowStage[];
  activeAt: GoogleBusinessProfileWorkflowStage[];
};

const STEPS: StepDef[] = [
  {
    key: 'review',
    label: 'Review & Approve',
    completedAt: ['approved', 'preflighted', 'publishing', 'published', 'partial_failure'],
    activeAt: ['no_draft', 'review'],
  },
  {
    key: 'publish',
    label: 'Publish Changes',
    completedAt: ['published'],
    activeAt: ['approved', 'preflighted', 'publishing', 'partial_failure'],
  },
];

function StepperIndicator({ stage }: { stage: GoogleBusinessProfileWorkflowStage }) {
  return (
    <ol
      className="flex flex-wrap items-center gap-2"
      aria-label="Approval workflow progress"
      data-testid="gbp-workflow-stepper"
    >
      {STEPS.map((step, i) => {
        const done = step.completedAt.includes(stage);
        const active = step.activeAt.includes(stage);
        const spinning = stage === 'publishing' && step.key === 'publish';
        const Icon = done ? CheckCircle2 : spinning ? Loader2 : Circle;
        return (
          <li
            key={step.key}
            data-stage-key={step.key}
            data-stage-state={done ? 'complete' : active ? 'active' : 'pending'}
            className="flex items-center gap-1.5"
          >
            {i > 0 ? (
              <span
                className={cn('mx-1 hidden h-px w-7 sm:block', done ? 'bg-primary' : 'bg-border')}
              />
            ) : null}
            <Icon
              className={cn(
                'size-4',
                done ? 'text-primary' : active ? 'text-primary' : 'text-muted-foreground/40',
                spinning && 'animate-spin',
              )}
            />
            <span
              className={cn(
                'text-xs font-medium',
                done ? 'text-foreground' : active ? 'text-foreground' : 'text-muted-foreground/50',
              )}
            >
              {step.label}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

/* ── Main component ─────────────────────────────── */

export function WorkflowCard({ restaurantId }: WorkflowCardProps) {
  const workflowQuery = useOpsGoogleBusinessProfileWorkflow(restaurantId);
  const createDraftMutation = useOpsCreateGoogleBusinessProfileDraft(restaurantId);
  const updateDraftMutation = useOpsUpdateGoogleBusinessProfileDraft(restaurantId);
  const preflightMutation = useOpsPreflightGoogleBusinessProfileDraftPublish(restaurantId);
  const publishMutation = useOpsPublishGoogleBusinessProfileDraft(restaurantId);

  const [selectedSectionKey, setSelectedSectionKey] = useState<string | null>(null);
  const [publishDialogOpen, setPublishDialogOpen] = useState(false);
  const [publishPreflight, setPublishPreflight] =
    useState<GoogleBusinessProfileDraftPublishPreflight | null>(null);

  const workflow = workflowQuery.data;
  const draft = workflow?.latestDraft ?? null;

  const stage = useMemo(() => deriveGoogleBusinessProfileWorkflowStage(workflow), [workflow]);

  const selectedItems = useMemo(() => buildDialogItems(workflow), [workflow]);

  const sections = useMemo(() => draft?.sectionDiffs ?? [], [draft]);

  const summaries = useMemo(() => buildSectionSummaries(sections), [sections]);

  const counts = useMemo(() => {
    let changed = 0;
    let selected = 0;
    let blocked = 0;
    for (const s of summaries as {
      changedCount: number;
      selectedCount: number;
      blockedCount: number;
    }[]) {
      changed += s.changedCount;
      selected += s.selectedCount;
      blocked += s.blockedCount;
    }
    return { changed, selected, blocked };
  }, [summaries]);

  const activeSummary = useMemo(
    () =>
      summaries.find(
        (s: { section: { sectionKey: string } }) => s.section.sectionKey === selectedSectionKey,
      ) ?? null,
    [summaries, selectedSectionKey],
  );

  // Auto-select first active section when draft loads
  const handleSectionSelect = useCallback((key: string) => {
    setSelectedSectionKey(key);
  }, []);

  // If nothing selected yet but sections exist, pick first active.
  useEffect(() => {
    if (
      selectedSectionKey &&
      summaries.some(
        (s: { section: { sectionKey: string } }) => s.section.sectionKey === selectedSectionKey,
      )
    ) {
      return;
    }
    const firstActive = summaries.find((s: { isActive: boolean }) => s.isActive);
    if (firstActive) {
      setSelectedSectionKey(firstActive.section.sectionKey);
    } else if (summaries[0]) {
      setSelectedSectionKey(summaries[0].section.sectionKey);
    }
  }, [summaries, selectedSectionKey]);

  const visibleAuditEvents = useMemo(
    () =>
      workflow?.auditEvents.filter((e) => e.direction !== 'push_from_nabatable_to_google') ?? [],
    [workflow],
  );

  const isReviewPhase = stage === 'no_draft' || stage === 'review';
  const isPublishPhase =
    Boolean(draft) &&
    !draft?.staleSections.length &&
    (stage === 'approved' ||
      stage === 'preflighted' ||
      stage === 'publishing' ||
      stage === 'partial_failure');
  const canApprove =
    Boolean(draft) && isReviewPhase && !draft?.staleSections.length && counts.selected > 0;
  const canPublish = isPublishPhase && selectedItems.length > 0;

  const fetchedLabel = draft?.fetchedAt ? formatGbpDateTime(draft.fetchedAt) : null;
  const completionPercent =
    counts.changed > 0 ? Math.round((counts.selected / counts.changed) * 100) : 0;

  return (
    <div className="flex flex-col gap-4" data-testid="gbp-workflow-card">
      <Card className="overflow-hidden border-border/70 shadow-sm">
        <CardHeader className="gap-5 border-b bg-muted/20 sm:flex-row sm:items-start sm:justify-between sm:space-y-0">
          <div className="flex max-w-4xl flex-col gap-3">
            <div className="flex flex-wrap items-center gap-2">
              <Badge variant="outline" className="w-fit font-medium">
                Read-only approval review
              </Badge>
              <Badge variant="secondary" className="gap-1 text-[11px]">
                <ArrowRightLeft className="size-3" aria-hidden />
                Google to Nabatable
              </Badge>
              <Badge variant="outline" className="text-[11px]">
                No Google write
              </Badge>
            </div>
            <div className="flex flex-col gap-2">
              <CardTitle className="text-balance text-2xl">Approval workflow</CardTitle>
              <CardDescription className="max-w-3xl">
                Compare the latest Google Business Profile values against Nabatable, confirm the
                approved selections, then publish only the reviewed changes into Nabatable.
              </CardDescription>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <StepperIndicator stage={stage} />
              {draft ? (
                <Badge variant={statusVariant(draft.status)} className="text-[11px]">
                  {formatDraftStatusLabel(draft.status)}
                </Badge>
              ) : null}
            </div>
          </div>

          <div className="flex w-full flex-wrap items-center gap-2 sm:w-auto sm:justify-end">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() =>
                createDraftMutation.mutate(undefined, {
                  onSuccess: () => workflowQuery.refetch(),
                })
              }
              disabled={createDraftMutation.isPending}
            >
              <RefreshCw
                className={cn('size-3.5', createDraftMutation.isPending && 'animate-spin')}
                data-icon="inline-start"
              />
              {createDraftMutation.isPending ? 'Refreshing…' : 'Refresh draft'}
            </Button>

            {isReviewPhase && draft ? (
              <Button
                type="button"
                size="sm"
                onClick={() =>
                  updateDraftMutation.mutate(
                    { draftId: draft.id, payload: { status: 'approved' } },
                    { onSuccess: () => workflowQuery.refetch() },
                  )
                }
                disabled={!canApprove || updateDraftMutation.isPending}
                data-testid="gbp-approve-button"
              >
                <CheckCircle2 className="size-3.5" data-icon="inline-start" />
                {updateDraftMutation.isPending ? 'Approving…' : `Approve (${counts.selected})`}
              </Button>
            ) : null}

            {isPublishPhase ? (
              <Button
                type="button"
                size="sm"
                onClick={() => {
                  setPublishPreflight(null);
                  preflightMutation.reset();
                  setPublishDialogOpen(true);
                }}
                disabled={!canPublish || publishMutation.isPending}
                data-testid="gbp-publish-button"
              >
                <Send className="size-3.5" data-icon="inline-start" />
                Publish ({selectedItems.length})
              </Button>
            ) : null}
          </div>
        </CardHeader>

        {draft ? (
          <CardContent className="grid gap-0 p-0 sm:grid-cols-3">
            <div className="border-b px-5 py-4 sm:border-b-0 sm:border-r">
              <p className="text-xs font-medium text-muted-foreground">Review coverage</p>
              <p
                className="mt-1 text-2xl font-semibold tabular-nums text-foreground"
                data-testid="gbp-selected-count"
              >
                {counts.selected}/{counts.changed}
              </p>
              <p className="text-xs text-muted-foreground">{completionPercent}% selected</p>
            </div>
            <div className="border-b px-5 py-4 sm:border-b-0 sm:border-r">
              <p className="text-xs font-medium text-muted-foreground">Blocked items</p>
              <p
                className={cn(
                  'mt-1 text-2xl font-semibold tabular-nums',
                  counts.blocked > 0 ? 'text-destructive' : 'text-foreground',
                )}
              >
                {counts.blocked}
              </p>
              <p className="text-xs text-muted-foreground">
                {counts.blocked > 0 ? 'Needs a fresh or supported value' : 'No blockers in draft'}
              </p>
            </div>
            <div className="px-5 py-4">
              <p className="text-xs font-medium text-muted-foreground">Draft fetched</p>
              <p className="mt-1 text-sm font-semibold tabular-nums text-foreground">
                {fetchedLabel ?? 'Not fetched'}
              </p>
              <p className="text-xs text-muted-foreground">Read-only comparison snapshot</p>
            </div>
          </CardContent>
        ) : null}
      </Card>

      {workflowQuery.error ? (
        <Alert variant="destructive">
          <AlertTitle>Workflow unavailable</AlertTitle>
          <AlertDescription>{workflowQuery.error.message}</AlertDescription>
        </Alert>
      ) : null}

      {draft?.staleSections.length ? (
        <Alert variant="destructive">
          <AlertTitle>Draft is stale</AlertTitle>
          <AlertDescription>
            Refresh the draft before publishing: {draft.staleSections.join(', ')}.
          </AlertDescription>
        </Alert>
      ) : null}

      <Card className="overflow-hidden border-border/70">
        <CardContent className="p-0">
          {!draft && !workflowQuery.isLoading ? (
            <div
              className="flex min-h-[320px] items-center justify-center p-8 text-center"
              data-testid="gbp-no-draft"
            >
              <div className="flex max-w-md flex-col items-center gap-4">
                <div className="mx-auto flex size-16 items-center justify-center rounded-full bg-muted/60">
                  <GitPullRequestArrow className="size-7 text-muted-foreground/50" />
                </div>
                <div className="flex flex-col gap-1.5">
                  <p className="text-base font-semibold text-foreground">No review draft yet</p>
                  <p className="text-sm text-muted-foreground">
                    Generate a draft to compare what is on Google Business Profile against
                    Nabatable. Use <span className="font-medium">Refresh draft</span> above to fetch
                    the latest from Google and build a reviewable change list.
                  </p>
                </div>
              </div>
            </div>
          ) : null}

          {draft ? (
            <div
              className="grid min-h-[560px] grid-cols-1 lg:grid-cols-[320px_1fr]"
              data-testid="gbp-split-pane"
            >
              <div className="border-b border-border/60 lg:border-b-0 lg:border-r lg:border-border/60">
                <SectionInbox
                  summaries={summaries}
                  selectedKey={selectedSectionKey}
                  onSelect={handleSectionSelect}
                  totalSelected={counts.selected}
                  totalChanged={counts.changed}
                />
              </div>

              <div className="min-h-0">
                <DetailInspector summary={activeSummary} />
              </div>
            </div>
          ) : null}
        </CardContent>
        {visibleAuditEvents.length > 0 ? (
          <CardFooter className="flex-col items-stretch gap-3 border-t bg-muted/20 px-5 py-4">
            <div className="flex items-center justify-between gap-3">
              <p className="text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground/70">
                Recent audit
              </p>
              <Badge variant="outline" className="text-[10px]">
                {visibleAuditEvents.length} event{visibleAuditEvents.length === 1 ? '' : 's'}
              </Badge>
            </div>
            <div className="grid gap-2 md:grid-cols-2">
              {visibleAuditEvents.slice(0, 4).map((event) => (
                <div
                  key={event.id}
                  className="flex min-w-0 items-center justify-between gap-3 rounded-md border bg-background px-3 py-2 text-xs"
                >
                  <div className="min-w-0">
                    <p className="truncate font-medium text-foreground">
                      {formatAuditDirectionLabel(event)}
                    </p>
                    <p className="truncate text-muted-foreground">
                      {event.affectedSections.join(', ') || 'No sections'}
                    </p>
                  </div>
                  <Badge variant={statusVariant(event.result)} className="shrink-0 text-[10px]">
                    {event.result}
                  </Badge>
                </div>
              ))}
            </div>
          </CardFooter>
        ) : null}
      </Card>

      <GoogleBusinessProfileSyncActionDialog
        open={publishDialogOpen}
        onOpenChange={(open: boolean) => {
          setPublishDialogOpen(open);
          if (!open) {
            setPublishPreflight(null);
            preflightMutation.reset();
          }
        }}
        title="Publish approved GBP draft"
        description="Publish approved Google Business Profile changes into Nabatable. This does not write back to Google."
        confirmLabel="Publish"
        selectionLabel="These items were approved in Step 1 and will publish."
        items={selectedItems}
        preflight={publishPreflight}
        isPreflightPending={preflightMutation.isPending}
        preflightErrorMessage={preflightMutation.error?.message ?? null}
        onPreflightReset={() => {
          setPublishPreflight(null);
          preflightMutation.reset();
        }}
        onPreflight={async () => {
          if (!draft) return;
          const pf = await preflightMutation.mutateAsync({
            draftId: draft.id,
            payload: {
              selectedApprovals: draft.selectedApprovals,
              directionIntent: 'google_to_nabatable',
            },
          });
          setPublishPreflight(pf);
        }}
        isPending={publishMutation.isPending}
        errorMessage={publishMutation.error?.message ?? null}
        onConfirm={async ({ password }: { password: string }) => {
          if (!draft || !publishPreflight) return;
          await publishMutation.mutateAsync({
            draftId: draft.id,
            payload: {
              password,
              publishJobId: publishPreflight.publishJobId,
              idempotencyKey: publishPreflight.idempotencyKey,
              selectedApprovals: draft.selectedApprovals,
              directionIntent: 'google_to_nabatable',
            },
          });
          setPublishDialogOpen(false);
          setPublishPreflight(null);
          void workflowQuery.refetch();
        }}
      />
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';

import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { cn } from '@/lib/utils';

import type { GoogleBusinessProfilePublishDirectionIntent } from '@/services/ops/restaurants';

export type GoogleBusinessProfileSyncActionItem = {
  id: string;
  label: string;
  description?: string;
  details?: string[];
  group?: string;
  supportLabel?: string;
  disabled?: boolean;
  defaultChecked?: boolean;
};

type GoogleBusinessProfileSyncActionPreflight = {
  publishJobId: string;
  idempotencyKey: string;
  directionIntent: GoogleBusinessProfilePublishDirectionIntent;
  googleUpdateMasks: string[];
  warnings: Array<{ message: string }>;
  errors: Array<{ message: string }>;
  canPushToGoogle: boolean;
};

type GoogleBusinessProfileSyncActionDialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: string;
  confirmLabel: string;
  isPending?: boolean;
  errorMessage?: string | null;
  passwordLabel?: string;
  passwordDescription?: string;
  selectionLabel?: string;
  /**
   * Items to display. By default they render as a read-only summary (the
   * selection lives in Step 1 of the parent workflow). Pass
   * `selectionEditable` to opt into the legacy editable-checkbox UX for
   * surfaces that still own selection at confirm-time (e.g. service-period
   * import/export dialogs).
   */
  items?: GoogleBusinessProfileSyncActionItem[];
  /**
   * When true, items render with editable checkboxes and `selectedIds` in
   * callbacks reflects the user choice. When false (default), items render
   * read-only and callbacks always include the full item id list.
   */
  selectionEditable?: boolean;
  directionIntent?: GoogleBusinessProfilePublishDirectionIntent;
  preflight?: GoogleBusinessProfileSyncActionPreflight | null;
  preflightLabel?: string;
  isPreflightPending?: boolean;
  preflightErrorMessage?: string | null;
  onPreflight?: (params: {
    selectedIds: string[];
    directionIntent: GoogleBusinessProfilePublishDirectionIntent;
  }) => void | Promise<void>;
  onPreflightReset?: () => void;
  onConfirm: (params: {
    password: string;
    selectedIds: string[];
    directionIntent: GoogleBusinessProfilePublishDirectionIntent;
  }) => void | Promise<void>;
};

function buildInitialSelection(items: GoogleBusinessProfileSyncActionItem[]) {
  const explicitDefaults = items
    .filter((item) => item.defaultChecked && !item.disabled)
    .map((item) => item.id);
  if (explicitDefaults.length > 0) {
    return explicitDefaults;
  }
  return items.filter((item) => !item.disabled).map((item) => item.id);
}

export function GoogleBusinessProfileSyncActionDialog({
  open,
  onOpenChange,
  title,
  description,
  confirmLabel,
  isPending = false,
  errorMessage,
  passwordLabel = 'Confirm with your login password',
  passwordDescription = 'This extra confirmation prevents accidental GBP changes and records that you approved the pending sync.',
  selectionLabel,
  items = [],
  selectionEditable = false,
  directionIntent = 'google_to_nabatable',
  preflight = null,
  preflightLabel = 'Preflight publish',
  isPreflightPending = false,
  preflightErrorMessage,
  onPreflight,
  onPreflightReset,
  onConfirm,
}: GoogleBusinessProfileSyncActionDialogProps) {
  const [password, setPassword] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  useEffect(() => {
    if (!open) return;
    setPassword('');
    setSelectedIds(
      selectionEditable
        ? buildInitialSelection(items)
        : items.filter((item) => !item.disabled).map((item) => item.id),
    );
  }, [items, open, selectionEditable]);

  const groupedItems = useMemo(() => {
    const groups = new Map<string, GoogleBusinessProfileSyncActionItem[]>();
    for (const item of items) {
      const group = item.group ?? 'Items';
      const current = groups.get(group) ?? [];
      current.push(item);
      groups.set(group, current);
    }
    return [...groups.entries()];
  }, [items]);

  const selectableItems = useMemo(() => items.filter((item) => !item.disabled), [items]);
  const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);
  const hasItems = items.length > 0;
  const allSelected =
    selectableItems.length > 0 && selectableItems.every((item) => selectedIdSet.has(item.id));
  const requiresPreflight = Boolean(onPreflight);
  const preflightComplete = !requiresPreflight || Boolean(preflight);
  const resolvedSelectionLabel =
    selectionLabel ??
    (selectionEditable
      ? 'Choose the items to include in this action.'
      : 'These items were approved in Step 1 and will publish.');

  const resetPreflight = () => {
    onPreflightReset?.();
  };

  const toggleItem = (itemId: string, checked: boolean) => {
    resetPreflight();
    setSelectedIds((current) => {
      if (checked) {
        return [...new Set([...current, itemId])];
      }
      return current.filter((id) => id !== itemId);
    });
  };

  const handleConfirm = () => {
    void onConfirm({
      password: password.trim(),
      selectedIds,
      directionIntent,
    });
  };

  const handlePreflight = () => {
    void onPreflight?.({ selectedIds, directionIntent });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>

        <div className="space-y-5">
          {hasItems ? (
            <div
              className="space-y-3 rounded-xl border border-border/70 bg-muted/20 p-4"
              data-testid="gbp-publish-summary"
            >
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="space-y-1">
                  <p className="text-sm font-medium text-foreground">
                    {selectionEditable ? 'Selection' : 'Will publish'}
                  </p>
                  <p className="text-xs text-muted-foreground">{resolvedSelectionLabel}</p>
                </div>
                {selectionEditable ? (
                  <div className="flex items-center gap-2">
                    <Badge variant="secondary">
                      {selectedIds.length}/{selectableItems.length} selected
                    </Badge>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => {
                        resetPreflight();
                        setSelectedIds(selectableItems.map((item) => item.id));
                      }}
                      disabled={selectableItems.length === 0 || allSelected || isPending}
                    >
                      Select all
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => {
                        resetPreflight();
                        setSelectedIds([]);
                      }}
                      disabled={selectedIds.length === 0 || isPending}
                    >
                      Clear
                    </Button>
                  </div>
                ) : (
                  <Badge variant="secondary">{items.length} approved</Badge>
                )}
              </div>

              <div className="space-y-4">
                {groupedItems.map(([group, groupItems]) => (
                  <div key={group} className="space-y-2">
                    <p className="text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">
                      {group}
                    </p>
                    <div className="space-y-2">
                      {groupItems.map((item) => {
                        const checked = selectedIdSet.has(item.id);
                        if (!selectionEditable) {
                          return (
                            <div
                              key={item.id}
                              className="space-y-1 rounded-lg border border-border/60 bg-background/80 p-3"
                              data-testid="gbp-publish-summary-item"
                            >
                              <div className="flex flex-wrap items-center justify-between gap-2">
                                <p className="text-sm font-medium text-foreground">{item.label}</p>
                                {item.supportLabel ? (
                                  <Badge variant="outline">{item.supportLabel}</Badge>
                                ) : null}
                              </div>
                              {item.description ? (
                                <p className="text-xs text-muted-foreground">{item.description}</p>
                              ) : null}
                              {item.details?.length ? (
                                <div className="space-y-1">
                                  {item.details.map((detail) => (
                                    <p key={detail} className="text-xs text-muted-foreground">
                                      {detail}
                                    </p>
                                  ))}
                                </div>
                              ) : null}
                            </div>
                          );
                        }
                        return (
                          <label
                            key={item.id}
                            className={cn(
                              'flex cursor-pointer gap-3 rounded-lg border border-border/60 bg-background/80 p-3',
                              item.disabled && 'cursor-not-allowed opacity-60',
                            )}
                          >
                            <Checkbox
                              checked={checked}
                              disabled={item.disabled || isPending}
                              onCheckedChange={(value) => toggleItem(item.id, Boolean(value))}
                              aria-label={item.label}
                              className="mt-0.5"
                            />
                            <div className="space-y-1">
                              <p className="text-sm font-medium text-foreground">{item.label}</p>
                              {item.supportLabel ? (
                                <Badge variant="outline">{item.supportLabel}</Badge>
                              ) : null}
                              {item.description ? (
                                <p className="text-xs text-muted-foreground">{item.description}</p>
                              ) : null}
                              {item.details?.length ? (
                                <div className="space-y-1">
                                  {item.details.map((detail) => (
                                    <p key={detail} className="text-xs text-muted-foreground">
                                      {detail}
                                    </p>
                                  ))}
                                </div>
                              ) : null}
                            </div>
                          </label>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : null}

          {requiresPreflight ? (
            <div className="space-y-3 rounded-xl border border-border/70 bg-card/60 p-4">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="space-y-1">
	                  <p className="text-sm font-medium text-foreground">Preflight</p>
	                  <p className="text-xs text-muted-foreground">
	                    Confirm the approved Nabatable updates before entering a password.
	                  </p>
                </div>
                <Button
                  type="button"
                  variant={preflight ? 'outline' : 'default'}
                  onClick={handlePreflight}
                  disabled={
                    isPending ||
                    isPreflightPending ||
                    (selectionEditable && hasItems && selectedIds.length === 0)
                  }
                >
                  {isPreflightPending ? 'Checking...' : preflightLabel}
                </Button>
              </div>
	              {preflight ? (
	                <div className="space-y-2 text-xs text-muted-foreground">
	                  <div className="flex flex-wrap gap-2">
	                    <Badge variant="secondary">Google → Nabatable</Badge>
	                    <Badge variant="outline">No Google write</Badge>
	                  </div>
                  {preflight.warnings.map((warning) => (
                    <p key={warning.message}>{warning.message}</p>
                  ))}
                </div>
              ) : null}
              {preflightErrorMessage ? (
                <Alert variant="destructive">
                  <AlertTitle>Preflight failed</AlertTitle>
                  <AlertDescription>{preflightErrorMessage}</AlertDescription>
                </Alert>
              ) : null}
              {preflight?.errors.length ? (
                <Alert variant="destructive">
                  <AlertTitle>Preflight blocked</AlertTitle>
                  <AlertDescription>
                    {preflight.errors.map((error) => error.message).join(' ')}
                  </AlertDescription>
                </Alert>
              ) : null}
            </div>
          ) : null}

          <div className="space-y-2 rounded-xl border border-border/70 bg-card/60 p-4">
            <Label htmlFor="gbp-sync-password" className="text-sm font-medium text-foreground">
              {passwordLabel}
            </Label>
            <p className="text-xs text-muted-foreground">{passwordDescription}</p>
            <Input
              id="gbp-sync-password"
              type="password"
              autoComplete="current-password"
              placeholder="Enter your password"
              value={password}
              disabled={isPending || !preflightComplete}
              onChange={(event) => setPassword(event.target.value)}
            />
          </div>

          {errorMessage ? (
            <Alert variant="destructive">
              <AlertTitle>Action could not be completed</AlertTitle>
              <AlertDescription>{errorMessage}</AlertDescription>
            </Alert>
          ) : null}
        </div>

        <DialogFooter className="gap-2">
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isPending}
          >
            Cancel
          </Button>
          <Button
            type="button"
            onClick={handleConfirm}
            disabled={
              isPending ||
              !preflightComplete ||
              password.trim().length === 0 ||
              (selectionEditable && hasItems && selectedIds.length === 0)
            }
          >
            {isPending ? 'Confirming...' : confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import {
  useMutation,
  useQuery,
  useQueryClient,
  type UseMutationResult,
  type UseQueryResult,
} from '@tanstack/react-query';

import { useRestaurantService } from '@/contexts/ops-services';
import { queryKeys } from '@/lib/query/keys';
import {
  deriveGoogleBusinessProfileWorkflowStage,
  type GoogleBusinessProfileWorkflowStage,
} from '@/services/ops/restaurants';

import type { HttpError } from '@/lib/http/errors';
import type {
  GoogleBusinessProfileConnection,
  GoogleBusinessProfileDraftPatchPayload,
  GoogleBusinessProfileDraftPublishPayload,
  GoogleBusinessProfileDraftPublishPreflight,
  GoogleBusinessProfileDraftPublishPreflightPayload,
  GoogleBusinessProfileProtectedActionPayload,
  GoogleBusinessProfileWorkflow,
  LinkGoogleBusinessProfileLocationInput,
} from '@/services/ops/restaurants';

export function useOpsGoogleBusinessProfileWorkflowStage(
  restaurantId?: string | null,
): GoogleBusinessProfileWorkflowStage {
  const workflow = useOpsGoogleBusinessProfileWorkflow(restaurantId).data;
  return deriveGoogleBusinessProfileWorkflowStage(workflow);
}

export function useOpsGoogleBusinessProfileConnection(
  restaurantId?: string | null,
): UseQueryResult<GoogleBusinessProfileConnection, HttpError> {
  const restaurantService = useRestaurantService();

  return useQuery<GoogleBusinessProfileConnection, HttpError>({
    queryKey: restaurantId
      ? queryKeys.opsRestaurants.googleBusinessProfile(restaurantId)
      : queryKeys.opsRestaurants.googleBusinessProfile('none'),
    queryFn: () => {
      if (!restaurantId) {
        throw new Error('Restaurant id is required');
      }
      return restaurantService.getGoogleBusinessProfileConnection(restaurantId);
    },
    enabled: Boolean(restaurantId),
    staleTime: 30_000,
  });
}

export function useOpsLinkGoogleBusinessProfileLocation(
  restaurantId?: string | null,
): UseMutationResult<
  GoogleBusinessProfileConnection,
  HttpError | Error,
  LinkGoogleBusinessProfileLocationInput
> {
  const restaurantService = useRestaurantService();
  const queryClient = useQueryClient();

  return useMutation<
    GoogleBusinessProfileConnection,
    HttpError | Error,
    LinkGoogleBusinessProfileLocationInput
  >({
    mutationFn: (payload) => {
      if (!restaurantId) {
        throw new Error('Restaurant id is required');
      }
      return restaurantService.linkGoogleBusinessProfileLocation(restaurantId, payload);
    },
    onSuccess: (state) => {
      if (!restaurantId) return;
      queryClient.setQueryData(queryKeys.opsRestaurants.googleBusinessProfile(restaurantId), state);
    },
  });
}

export function useOpsDisconnectGoogleBusinessProfile(
  restaurantId?: string | null,
): UseMutationResult<GoogleBusinessProfileConnection, HttpError | Error, void> {
  const restaurantService = useRestaurantService();
  const queryClient = useQueryClient();

  return useMutation<GoogleBusinessProfileConnection, HttpError | Error, void>({
    mutationFn: () => {
      if (!restaurantId) {
        throw new Error('Restaurant id is required');
      }
      return restaurantService.disconnectGoogleBusinessProfileConnection(restaurantId);
    },
    onSuccess: (state) => {
      if (!restaurantId) return;
      queryClient.setQueryData(queryKeys.opsRestaurants.googleBusinessProfile(restaurantId), state);
    },
  });
}

export function useOpsSyncGoogleBusinessProfile(
  restaurantId?: string | null,
): UseMutationResult<
  GoogleBusinessProfileConnection,
  HttpError | Error,
  GoogleBusinessProfileProtectedActionPayload
> {
  const restaurantService = useRestaurantService();
  const queryClient = useQueryClient();

  return useMutation<
    GoogleBusinessProfileConnection,
    HttpError | Error,
    GoogleBusinessProfileProtectedActionPayload
  >({
    mutationFn: (payload) => {
