function getRestaurantSnapshot(state: MutableState, restaurantId: string): RestaurantSnapshot {
  const snapshot = state.restaurants[restaurantId];
  if (!snapshot) {
    throw new Error('[dev][restaurantService] unknown restaurant');
  }
  return snapshot;
}

