    );

    expect(screen.queryByText(/publish direction/i)).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /also sync supported fields/i })).not.toBeInTheDocument();
  });

  it('renders without items for password-only confirmation flows', async () => {
    const user = userEvent.setup();
    const onConfirm = vi.fn();

    render(
      <GoogleBusinessProfileSyncActionDialog
        open
        onOpenChange={vi.fn()}
        title="Confirm action"
        description="Confirm the action."
        confirmLabel="Confirm"
        items={[]}
        onConfirm={onConfirm}
      />,
    );

    expect(screen.queryByTestId('gbp-publish-summary')).not.toBeInTheDocument();
    await user.type(screen.getByLabelText(/confirm with your login password/i), 'secret');
    await user.click(screen.getByRole('button', { name: /^confirm$/i }));
    expect(onConfirm).toHaveBeenCalledWith({
      password: 'secret',
      selectedIds: [],
      directionIntent: 'google_to_nabatable',
    });
  });
});
